ss="py-3 px-3 text-right">Harga</th><th class="py-3 px-3 text-right">%chg</th><th class="py-3 px-3 text-center">Aksi</th><th class="py-3 px-3 text-right">Lot</th><th class="py-3 px-3 text-right">Nilai</th></tr></thead><tbody id="rt-table-body" class="divide-y divide-[#F5F1E8]/5"><tr><td colspan="7" class="py-8 text-center text-[#F5F1E8]/40">Menunggu state collector...</td></tr></tbody></table></div><p class="mt-3 text-[10px] text-amber-300/80 font-mono">BOARD_SCOPE_UNVERIFIED — data tidak boleh dipakai sebagai bukti RG, sinyal, atau order.</p></section>
</div>
<script>
(() => {
    const $ = id => document.getElementById(id), endpoint = '{{ route("dashboard.market.running_trade_state") }}';
    let inFlight = false, latestTrades = [], actionFilter = 'all', topMetric = 'freq';
    const safe = value => String(value ?? '-').replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'}[c]));
    const number = value => value === null || value === undefined || !Number.isFinite(Number(value)) ? 'N/A' : Number(value).toLocaleString('id-ID');
    const pct = value => value === null || value === undefined || !Number.isFinite(Number(value)) ? 'N/A' : `${Number(value) > 0 ? '+' : ''}${Number(value).toFixed(1)}%`;
    function renderTable() {
        const code = $('rt-code-filter').value.trim().toUpperCase(), minLot = Number($('rt-min-lot').value || 0), minValue = Number($('rt-min-value').value || 0);
        const rows = latestTrades.filter(t => (!code || String(t.ticker || '').toUpperCase().includes(code)) && (actionFilter === 'all' || String(t.c_raw ?? t.action ?? '').toLowerCase() === actionFilter) && Number(t.lot || 0) >= minLot && Number(t.value_idr || t.value || 0) >= minValue);
        $('rt-count').textContent = `(${rows.length})`; $('rt-filter-status').textContent = `${actionFilter === 'all' ? 'Semua' : actionFilter.toUpperCase()} · ${rows.length} dari ${latestTrades.length}`;
        $('rt-table-body').innerHTML = rows.slice(0, 100).map(t => { const action = String(t.c_raw ?? t.action ?? '').toLowerCase(), chg = Number(t.change_pct); return `<tr><td class="py-2 px-3 text-[#F5F1E8]/60">${safe(t.event_time)}</td><td class="py-2 px-3 font-bold">${safe(t.ticker)}</td><td class="py-2 px-3 text-right">${number(t.price)}</td><td class="py-2 px-3 text-right ${chg >= 0 ? 'text-[#3FB950]' : 'text-[#F85149]'}">${pct(t.change_pct)}</td><td class="py-2 px-3 text-center"><span class="rounded px-2 py-1 text-[10px] ${action === 'buy' ? 'bg-emerald-950 text-emerald-300' : action === 'sell' ? 'bg-rose-950 text-rose-300' : 'bg-[#0D2B4E] text-[#F5F1E8]/60'}">${safe(action ? action[0].toUpperCase() + action.slice(1) : 'N/A')}</span></td><td class="py-2 px-3 text-right">${number(t.lot)}</td><td class="py-2 px-3 text-right">${number(t.value_idr)}</td></tr>`; }).join('') || '<tr><td colspan="7" class="py-8 text-center text-[#F5F1E8]/40">Belum ada transaksi sesuai filter.</td></tr>';
    }
    function renderTop(data) {
        const rows = data.top5_snapshots?.boards?.[topMetric] || data.top5_snapshots?.snapshot_data || [], list = Array.isArray(rows) ? rows.slice(0, 5) : Object.entries(rows).map(([ticker, value]) => ({ ticker, value }));
        $('rt-top-cards').innerHTML = list.length ? list.map(item => { const ticker = item.ticker ?? item.code ?? item.t ?? 'N/A', value = item.freq ?? item.count ?? item.metric ?? item.lot ?? item.value ?? item.net_value ?? item.net_buy ?? item.net_sell; return `<article class="rounded border border-[#F5F1E8]/10 bg-[#05152B] p-3"><div class="flex items-center justify-between"><strong class="text-sm">${safe(ticker)}</strong><span class="text-[10px] text-[#F5F1E8]/50">${number(value)} ${topMetric === 'freq' ? 'trx' : topMetric}</span></div><div class="mt-2 text-sm">${number(item.last_price ?? item.price ?? item.p)}</div><div class="text-[11px] ${Number(item.last_change_pct ?? item.change_pct ?? item.pc) >= 0 ? 'text-[#3FB950]' : 'text-[#F85149]'}">${Number(item.last_change_pct ?? item.change_pct ?? item.pc) >= 0 ? '↗' : '↘'} ${pct(item.last_change_pct ?? item.change_pct ?? item.pc)}</div></article>`; }).join('') : '<div class="col-span-full py-5 text-center text-xs text-[#F5F1E8]/40">TOP5_NOT_AVAILABLE</div>';
    }
    document.querySelectorAll('[data-action-filter]').forEach(button => button.addEventListener('click', () => { actionFilter = button.dataset.actionFilter; document.querySelectorAll('[data-action-filter]').forEach(b => b.classList.remove('bg-[#0A213D]', 'text-[#9CCBFF]')); button.classList.add('bg-[#0A213D]', 'text-[#9CCBFF]'); renderTable(); }));
    document.querySelectorAll('[data-top-metric]').forEach(button => button.addEventListener('click', () => { topMetric = button.dataset.topMetric; document.querySelectorAll('[data-top-metric]').forEach(b => b.classList.remove('bg-[#0A213D]', 'text-[#9CCBFF]')); button.classList.add('bg-[#0A213D]', 'text-[#9CCBFF]'); renderTop(window.__rtLastState || {}); }));
    $('rt-apply-filter').addEventListener('click', renderTable); ['rt-code-filter','rt-min-lot','rt-min-value'].forEach(id => $(id).addEventListener('input', renderTable));
    $('rt-reset-filter').addEventListener('click', () => { $('rt-code-filter').value = ''; $('rt-min-lot').value = ''; $('rt-min-value').value = ''; document.querySelector('[data-action-filter="all"]').click(); });
    document.querySelector('[data-action-filter="all"]').click(); document.querySelector('[data-top-metric="freq"]').click();
    async function poll() { if (inFlight || document.hidden) return; inFlight = true; try { const response = await fetch(endpoint, { headers: { 'Accept': 'application/json' }, cache: 'no-store' }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const data = await response.json(); window.__rtLastState = data; latestTrades = Array.isArray(data.recent_trades) ? data.recent_trades.slice(0, 100) : []; const connected = data.status === 'CONNECTED' && data.session_date === new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta' }).format(new Date()); $('rt-live-badge').textContent = connected ? 'LIVE' : safe(data.status || 'DISCONNECTED'); $('rt-run-id').textContent = safe(data.run_id); $('rt-connection-id').textContent = safe(data.connection_id); $('rt-heartbeat').textContent = safe(data.last_heartbeat_at); $('rt-freshness').textContent = connected ? 'CURRENT' : safe(data.status); $('rt-last-trade').textContent = safe(data.last_trade_at); $('rt-board-scope').textContent = safe(data.board_scope || 'BOARD_SCOPE_UNVERIFIED'); renderTop(data); renderTable(); } catch (error) { $('rt-live-badge').textContent = 'STATE_UNAVAILABLE'; } finally { inFlight = false; } }
    poll(); const timer = setInterval(poll, 3000); document.addEventListener('visibilitychange', poll); window.addEventListener('pagehide', () => clearInterval(timer), { once: true });
})();
</script>
